const getDisplayDeviceStr = (task: Task) => {
  if (task.devices && task.devices.length > 0) {
    return task.devices.map(d => `${d.type === 'غير محدد' ? '' : (d.type || '')} ${d.brand === 'غير محدد' ? '' : (d.brand || '')}`.trim()).filter(Boolean).join(' + ');
  }
  const typeStr = task.deviceType === 'غير محدد' ? '' : (task.deviceType || '');
  const brandStr = task.brand === 'غير محدد' ? '' : (task.brand || '');
  return [typeStr, brandStr].filter(Boolean).join(' - ');
};

const getDeviceIconNameForTask = (task: Task | any, customMap?: Record<string, string>): string => {
  const iconMap = customMap || DEFAULT_DEVICE_TYPE_ICONS;
  let typeStr = "";
  if (task?.devices && Array.isArray(task.devices) && task.devices.length > 0) {
    typeStr = task.devices.map((d: any) => d.type || '').join(' ');
  } else if (task?.deviceType) {
    typeStr = task.deviceType;
  }

  let matchedIconName = 'Smartphone';

  if (typeStr) {
    const lower = typeStr.toLowerCase().trim();

    for (const [key, name] of Object.entries(iconMap)) {
      if (key && lower.includes(key.toLowerCase())) {
        matchedIconName = name as string;
        break;
      }
    }

    if (matchedIconName === 'Smartphone') {
      if (lower.includes('راوتر') || lower.includes('router')) matchedIconName = 'Router';
      else if (lower.includes('مودم') || lower.includes('modem')) matchedIconName = 'Wifi';
      else if (lower.includes('ستارلينك') || lower.includes('starlink')) matchedIconName = 'Disc';
      else if (lower.includes('طبق') || lower.includes('بث') || lower.includes('رأس')) matchedIconName = 'Radio';
      else if (lower.includes('انتينة') || lower.includes('antenna')) matchedIconName = 'Signal';
      else if (lower.includes('يوبيكويتي') || lower.includes('ubiquity') || lower.includes('ubiquiti')) matchedIconName = 'Satellite';
      else if (lower.includes('سويتش') || lower.includes('switch') || lower.includes('موزع') || lower.includes('منافذ')) matchedIconName = 'Network';
      else if (lower.includes('كاميرا') || lower.includes('camera')) matchedIconName = 'Camera';
      else if (lower.includes('متقدم') || lower.includes('الكتروني') || lower.includes('بورد') || lower.includes('معالج') || lower.includes('cpu')) matchedIconName = 'Cpu';
    }
  }

  return matchedIconName;
};

const safeConfirm = (msg: string) => {
  try {
    return window.confirm(msg);
  } catch(e) {
    console.warn("window.confirm blocked, allowing action:", e);
    return true;
  }
};

