const normalizeName = (name: string) => {
  if (!name) return '';
  // Remove parentheses and numbers inside them (allowing spaces), and normalize spaces
  return name.replace(/\(\s*\d+\s*\)/g, '').replace(/\s+/g, ' ').trim().toLowerCase();
};

const matchesViewType = (t: Task, viewType: string) => {
  if (viewType === 'all') return true;
  const taskDate = new Date(t.createdAt);
  const now = new Date();
  if (viewType === 'day') {
    return taskDate.toDateString() === now.toDateString();
  }
  if (viewType === 'week') {
    const day = now.getDay();
    const diffToSaturday = day === 6 ? 0 : day + 1;
    const startOfWeek = new Date(now);
    startOfWeek.setDate(now.getDate() - diffToSaturday);
    startOfWeek.setHours(0, 0, 0, 0);
    return taskDate >= startOfWeek;
  }
  if (viewType === 'month') {
    const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1, 0, 0, 0, 0);
    return taskDate >= startOfMonth;
  }
  if (viewType === 'year') {
    const startOfYear = new Date(now.getFullYear(), 0, 1, 0, 0, 0, 0);
    return taskDate >= startOfYear;
  }
  return true;
};

