  const handleHeaderMenuClick = (e: React.MouseEvent) => {
    e.preventDefault();
    const currentTime = Date.now();
    const timeDiff = currentTime - lastHeaderClickTimeRef.current;
    
    if (timeDiff < 300) {
      // نقرتين متتاليتين (Double Click)
      if (headerClickTimeoutRef.current) {
        clearTimeout(headerClickTimeoutRef.current);
        headerClickTimeoutRef.current = null;
      }
      lastHeaderClickTimeRef.current = 0; // إعادة ضبط
      
      if (!isSidebarActive) {
        // تفعيل عرض القائمة الجانبية وإخفاء البطاقات الست
        setIsSidebarActive(true);
        setHideMainCards(true);
        setIsSidebarOpen(true); // لفتح القائمة تلقائياً عند التفعيل
      } else {
        // إلغاء تفعيل عرض القائمة الجانبية وإظهار البطاقات
        setIsSidebarActive(false);
        setHideMainCards(false);
         // إغلاق القائمة
      }
    } else {
      // نقرة واحدة (Single Click)
      lastHeaderClickTimeRef.current = currentTime;
      if (headerClickTimeoutRef.current) {
        clearTimeout(headerClickTimeoutRef.current);
      }
      headerClickTimeoutRef.current = setTimeout(() => {
        if (isSidebarActive) {
          // فتح أو إغلاق القائمة الجانبية على جانب الشاشة
          setIsSidebarOpen(prev => !prev);
        } else {
          // إخفاء أو إظهار بطاقات الصفحة الرئيسية
          setHideMainCards(prev => !prev);
        }
        headerClickTimeoutRef.current = null;
      }, 250);
    }
  };

  const touchStartXRef = useRef<number | null>(null);
  const touchStartYRef = useRef<number | null>(null);
  const isMouseDraggingRef = useRef(false);
  const lastMouseYRef = useRef<number | null>(null);

  const handlePointerDown = (e: React.PointerEvent) => {
    touchStartXRef.current = e.clientX;
    touchStartYRef.current = e.clientY;
    
    if (e.pointerType === 'mouse') {
      const target = e.target as HTMLElement;
      if (target.tagName !== 'INPUT' && target.tagName !== 'TEXTAREA' && target.tagName !== 'SELECT') {
        isMouseDraggingRef.current = true;
        lastMouseYRef.current = e.clientY;
      }
    }
  };
  
  const handlePointerMove = (e: React.PointerEvent) => {
    if (e.pointerType === 'mouse' && isMouseDraggingRef.current && lastMouseYRef.current !== null) {
      // Allow dragging text so we don't prevent default, but do scroll
      const deltaY = e.clientY - lastMouseYRef.current;
      if (Math.abs(deltaY) > 0) {
        window.scrollBy({ top: -deltaY, behavior: 'instant' });
        // Since we are moving the page under the mouse, we shouldn't update lastMouseYRef with the *new* clientY 
        // relative to the screen if the window scrolled, wait, clientY is relative to the viewport.
        // If we scroll the window down by -deltaY, the element under mouse moves up.
        // It's usually better to just use movementY if available, or just update lastMouseYRef.
        lastMouseYRef.current = e.clientY;
      }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    isMouseDraggingRef.current = false;
    lastMouseYRef.current = null;
    
    if (touchStartXRef.current === null || touchStartYRef.current === null) return;
    
    const diffX = e.clientX - touchStartXRef.current;
    const diffY = e.clientY - touchStartYRef.current;
    
    // التحقق من أن الحركة أفقية وبمسافة كافية تمنع الأخطاء أثناء التمرير الرأسي العادي
    if (Math.abs(diffX) > Math.abs(diffY) && Math.abs(diffX) > 50) {
      if (isSidebarOpen) {
        if (sidebarPosition === 'left') {
          if (diffX < -40) setIsSidebarOpen(false);
        } else {
          if (diffX > 40) setIsSidebarOpen(false);
        }
      } else {
        const screenWidth = window.innerWidth;
        if (sidebarPosition === 'left') {
          if (diffX > 50 && touchStartXRef.current < 60) setIsSidebarOpen(true);
        } else {
          if (diffX < -50 && touchStartXRef.current > screenWidth - 60) setIsSidebarOpen(true);
        }
      }
    }
    
    touchStartXRef.current = null;
    touchStartYRef.current = null;
  };

  const handleSidebarTouchStart = (e: React.TouchEvent) => {
    const touch = e.touches[0];
    touchStartXRef.current = touch.clientX;
    touchStartYRef.current = touch.clientY;
  };

  const handleSidebarTouchEnd = (e: React.TouchEvent) => {
    if (touchStartXRef.current === null || touchStartYRef.current === null) return;
    
    const touch = e.changedTouches[0];
    const diffX = touch.clientX - touchStartXRef.current;
    const diffY = touch.clientY - touchStartYRef.current;
    
    if (Math.abs(diffX) > Math.abs(diffY) && Math.abs(diffX) > 40) {
      if (sidebarPosition === 'left') {
        if (diffX < -30) {
          setIsSidebarOpen(false);
        }
      } else {
        if (diffX > 30) {
          setIsSidebarOpen(false);
        }
      }
    }
    
    touchStartXRef.current = null;
    touchStartYRef.current = null;
  };

  const [showOnlyCritical, setShowOnlyCritical] = useState<boolean>(false);
  const [showNotificationsDropdown, setShowNotificationsDropdown] = useState<boolean>(false);
  const [lastLogoutClick, setLastLogoutClick] = useState<number>(0);
  const [showExitHint, setShowExitHint] = useState<boolean>(false);
  
  
