      const savedSettings = JSON.parse(localStorage.getItem('faisali_settings') || '[]');
      const uiSettingsObj = savedSettings.find((s: any) => s.key === 'uiSettings');
      return (uiSettingsObj?.value?.defaultDashboardTaskSort) || 'createdAt_desc';
