  useEffect(() => {
    localStorage.setItem('faisali_reminders', JSON.stringify(reminders));
  }, [reminders]);

  const [uiSettings, setUiSettings] = useState(DEFAULT_UI_SETTINGS);
  const [isToolsRevealed, setIsToolsRevealed] = useState(false);



  useEffect(() => {
    const handleMouseMove = (e: MouseEvent | TouchEvent) => {
      if (!isDraggingFloating) return;
      if ('touches' in e) {
        e.preventDefault();
      }
      const clientX = 'touches' in e ? e.touches[0].clientX : (e as MouseEvent).clientX;
      const clientY = 'touches' in e ? e.touches[0].clientY : (e as MouseEvent).clientY;
      
      const dx = clientX - dragStartRef.current.x;
      const dy = clientY - dragStartRef.current.y;
      if (Math.hypot(dx, dy) > 4) {
        hasDraggedRef.current = true;
      }

      if (hasDraggedRef.current) {
        const newX = Math.max(10, Math.min(window.innerWidth - 60, initialPosRef.current.x + dx));
        const newY = Math.max(10, Math.min(window.innerHeight - 60, initialPosRef.current.y + dy));
        setUiSettings(prev => ({
          ...prev,
          floatingIconX: newX,
          floatingIconY: newY
        }));
      }
    };

    const handleMouseUp = async () => {
      setIsDraggingFloating(false);
      document.body.style.userSelect = '';
      if (hasDraggedRef.current) {
        lastDragTimeRef.current = Date.now();
        await db.settings.put({ key: 'uiSettings', value: uiSettings });
      }
    };

    if (isDraggingFloating) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      window.addEventListener('touchmove', handleMouseMove, { passive: false });
      window.addEventListener('touchend', handleMouseUp);
    }

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
      window.removeEventListener('touchmove', handleMouseMove);
      window.removeEventListener('touchend', handleMouseUp);
      document.body.style.userSelect = '';
    };
  }, [isDraggingFloating]);
  const reportRef = useRef<HTMLDivElement>(null);

  const uiSettingsSetting = useLiveQuery(() => db.settings.get('uiSettings'));

  useEffect(() => {
    if (uiSettingsSetting?.value) {
      let savedSettings = { ...uiSettingsSetting.value };
      
      // Fallback values for new appearance fields:
      let patchNeeded = false;
      Object.keys(DEFAULT_UI_SETTINGS).forEach((key) => {
        if (savedSettings[key] === undefined) {
          savedSettings[key] = (DEFAULT_UI_SETTINGS as any)[key];
          patchNeeded = true;
        }
      });

      if (savedSettings.statsBarItems) {
        let changedItems = false;
        if (!Array.isArray(savedSettings.statsBarItems) || savedSettings.statsBarItems.length !== 6 || savedSettings.statsBarItems.some((i: any) => i.id === 'inspected' || i.id === 'cancelledTasks' || i.label === 'تم الفحص والابلاغ' || i.label === 'ملغية')) {
          savedSettings.statsBarItems = [
            { id: 'pending', label: 'معلقة', statuses: ['pending'], color: 'red' },
            { id: 'inProgress', label: 'جاري التنفيذ', statuses: ['in-progress', 'reported-in-progress'], color: 'indigo' },
            { id: 'maintenanceDone', label: 'تمت الصيانة', statuses: ['maintenance-done'], color: 'emerald' },
            { id: 'readyToDeliver', label: 'للتسليم', statuses: ['ready-to-deliver'], color: 'teal' },
            { id: 'delivered', label: 'تم التسليم', statuses: ['completed'], color: 'green' },
            { id: 'archived', label: 'منتهية', statuses: ['archived'], color: 'purple' },
          ];
          changedItems = true;
        } else {
          savedSettings.statsBarItems.forEach((i: any) => {
            if (i.id === 'pending' && i.label !== 'معلقة') { i.label = 'معلقة'; changedItems = true; }
            if (i.id === 'inProgress' && i.label !== 'جاري التنفيذ') { i.label = 'جاري التنفيذ'; changedItems = true; }
            if (i.id === 'maintenanceDone' && i.label !== 'تمت الصيانة') { i.label = 'تمت الصيانة'; changedItems = true; }
            if (i.id === 'readyToDeliver' && i.label !== 'للتسليم') { i.label = 'للتسليم'; changedItems = true; }
            if (i.id === 'delivered' && i.label !== 'تم التسليم') { i.label = 'تم التسليم'; changedItems = true; }
            if (i.id === 'archived' && i.label !== 'منتهية') { i.label = 'منتهية'; changedItems = true; }
          });
        }
        if (changedItems) patchNeeded = true;
      }

      if (savedSettings.mainButtons) {
        let changed = false;
        savedSettings.mainButtons = savedSettings.mainButtons.map((btn: any) => {
           const isOld1 = btn.gradient === 'from-[#007aff] to-[#47a1ff]' || btn.gradient === 'from-slate-800 to-slate-900';
           const isOld2 = btn.gradient === 'from-[#34c759] to-[#60d67f]' || btn.gradient === 'from-emerald-600 to-emerald-700';
           const isOld3 = btn.gradient === 'from-[#ff9500] to-[#ffab33]' || btn.gradient === 'from-amber-500 to-amber-600';
           const isOld4 = btn.gradient === 'from-[#c571f0] to-[#df9ef7]' || btn.gradient === 'from-indigo-600 to-indigo-700';
           const isOld5 = btn.gradient === 'from-[#ff3b30] to-[#ff6961]' || btn.gradient === 'from-red-600 to-red-700';
           const isOld6 = btn.gradient === 'from-[#32ade6] to-[#59c1ee]' || btn.gradient === 'from-sky-600 to-sky-700';
           
           if ((isOld1 || btn.gradient === 'from-yellow-400 to-amber-500' || btn.gradient === 'from-yellow-200 to-amber-300') && btn.id === 'new-task') { btn.gradient = 'from-yellow-300 to-amber-400'; btn.color = 'amber'; btn.textColor = '#0f172a'; changed = true; }
           if ((isOld2 || btn.gradient === 'from-teal-500 to-emerald-600' || btn.gradient === 'from-emerald-200 to-teal-300') && btn.id === 'tasks') { btn.gradient = 'from-emerald-300 to-teal-400'; btn.color = 'emerald'; btn.textColor = '#0f172a'; changed = true; }
           if ((isOld3 || btn.gradient === 'from-indigo-500 to-indigo-700' || btn.gradient === 'from-indigo-200 to-blue-300') && btn.id === 'customers') { btn.gradient = 'from-indigo-300 to-blue-400'; btn.color = 'indigo'; btn.textColor = '#0f172a'; changed = true; }
           if ((isOld4 || btn.gradient === 'from-violet-500 to-purple-700' || btn.gradient === 'from-purple-200 to-fuchsia-300') && btn.id === 'inventory') { btn.gradient = 'from-fuchsia-300 to-purple-400'; btn.color = 'purple'; btn.textColor = '#0f172a'; changed = true; }
           if ((isOld5 || btn.gradient === 'from-red-500 to-red-700' || btn.gradient === 'from-red-200 to-pink-300') && btn.id === 'accounts') { btn.gradient = 'from-red-300 to-pink-400'; btn.color = 'rose'; btn.textColor = '#0f172a'; changed = true; }
           if ((isOld6 || btn.gradient === 'from-sky-500 to-blue-600' || btn.gradient === 'from-sky-200 to-cyan-300') && btn.id === 'reports') { btn.gradient = 'from-sky-300 to-cyan-400'; btn.color = 'blue'; btn.textColor = '#0f172a'; changed = true; }
           return btn;
        });
        if (changed) patchNeeded = true;
      }
      if (savedSettings.homeBgType === 'gradient' && savedSettings.homeBgGradientFrom === '#f8fafc' && savedSettings.homeBgGradientTo === '#eaeaea') {
        savedSettings.homeBgType = 'solid';
        savedSettings.homeBgSolid = '#f8fafc';
        patchNeeded = true;
      }
      
      // Initialize states from defaults if not already set (only once on load)
      const isFirstLoad = !(window as any).faisaliDefaultsLoaded;
      if (isFirstLoad) {
        if (savedSettings.defaultDashboardTaskSort) {
          setDashboardTaskSort(savedSettings.defaultDashboardTaskSort);
        }
        if (savedSettings.defaultDashboardTaskFilter) {
          setDashboardTaskFilter(savedSettings.defaultDashboardTaskFilter === 'by-status' ? 'active' : savedSettings.defaultDashboardTaskFilter);
        }
        (window as any).faisaliDefaultsLoaded = true;
      }

      // Force migration to light theme:
      if (!savedSettings.hasMigratedToLightV4) {
        Object.keys(DEFAULT_UI_SETTINGS).forEach((key) => {
          if (key !== 'mainButtons' && key !== 'windowTitles' && key !== 'defaultLandingTab' && key !== 'tasksViewMode') {
            savedSettings[key] = (DEFAULT_UI_SETTINGS as any)[key];
          }
        });
        savedSettings.hasMigratedToLightV4 = true;
        patchNeeded = true;
      }
      
      if (!savedSettings.hasMigratedToLighterButtonsV5) {
        savedSettings.mainButtons = DEFAULT_UI_SETTINGS.mainButtons;
        savedSettings.hasMigratedToLighterButtonsV5 = true;
        patchNeeded = true;
      }
      
      if (!savedSettings.hasMigratedToIOS9) {
        Object.keys(DEFAULT_UI_SETTINGS).forEach((key) => {
          if (key !== 'windowTitles' && key !== 'defaultLandingTab' && key !== 'tasksViewMode') {
            savedSettings[key] = (DEFAULT_UI_SETTINGS as any)[key];
          }
        });
        savedSettings.hasMigratedToIOS9 = true;
        patchNeeded = true;
      }

      if (patchNeeded) {
        db.settings.put({ key: 'uiSettings', value: savedSettings });
      }

      if (savedSettings.mainButtons) {
        let modified = false;
        savedSettings.mainButtons = savedSettings.mainButtons.map((btn: any) => {
          if (btn.id === 'reports' && btn.iconName === 'BarChart3') {
            modified = true;
            return { ...btn, iconName: 'ReportsMergedIcon' };
          }
          if (!btn.textColor) {
            modified = true;
            if (btn.gradient.includes('amber-200')) {
               return { ...btn, textColor: '#1e293b' }; // dark text for light button
            }
            return { ...btn, textColor: '#ffffff' };
          }
          return btn;
        });
        if (modified) {
          db.settings.put({ key: 'uiSettings', value: savedSettings });
        }
      }
      setUiSettings(savedSettings);
    }
  }, [uiSettingsSetting]);

