  const syncPaymentsToIssueText = (payments: { id: string, amount: number, currency: Currency, date: string, note?: string }[], currentText: string, showHassab: boolean) => {
    const accountLines = payments.map(p => {
      const date = new Date(p.date);
      const dateStr = date.toLocaleDateString('en-GB', { day: '2-digit', month: '2-digit', year: 'numeric' });
      const timeStr = date.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
      const noteStr = p.note ? ` (${p.note})` : '';
      return `[مبلغ: ${p.amount} ${p.currency}${noteStr}] - ${dateStr} ${timeStr}`;
    });
    
    const totalInSystem = payments.reduce((sum, item) => sum + convertAndRound(item.amount, item.currency, systemCurrency, exchangeRates), 0);
    const totalText = totalInSystem > 0 ? ` (إجمالي المقدم: ${totalInSystem} ${systemCurrency})` : '';
    const accountText = accountLines.join('       ') + totalText;
    const accountPrefix = 'الحساب: ';
    
    let newText = currentText || '';
    
    if (newText.includes(accountPrefix)) {
      // Find where "الحساب: " starts
      const startIndex = newText.indexOf(accountPrefix);
      // Find the next known prefix or the end of the string
      const prefixes = ['الأجهزة: ', 'المشكلة: ', 'الفحص: ', 'موقع الحفظ: ', 'الأصناف: ', 'الحالة: '];
      let endIndex = newText.length;
      
      for (const prefix of Object.values(prefixes)) {
        const pIdx = newText.indexOf(prefix, startIndex + accountPrefix.length);
        if (pIdx !== -1 && pIdx < endIndex) {
          endIndex = pIdx;
        }
      }
      
      if (!showHassab || payments.length === 0) {
        newText = newText.slice(0, startIndex) + newText.slice(endIndex);
      } else {
        newText = newText.slice(0, startIndex) + accountPrefix + accountText + '' + newText.slice(endIndex);
      }
    } else {
      if (showHassab && payments.length > 0) {
        newText = newText + '' + accountPrefix + accountText + '';
      }
    }
    
    return newText.trim();
  };
  const [taskCustomerPhones, setTaskCustomerPhones] = useState<string[]>([]);
  const [isPhoneManagerOpen, setIsPhoneManagerOpen] = useState(false);
