  const getWhatsAppFormattedTextForTask = (task: Task) => {
    const defaultWhatsAppTemplateId = (uiSettings as any)?.defaultWhatsAppTemplateId;
    const templateContent = (defaultWhatsAppTemplateId ? taskTemplates.find(t => t.id === defaultWhatsAppTemplateId)?.content : null) || taskTemplates.find(t => t.id === 'd1')?.content || taskTemplates.find(t => t.type === 'detailed')?.content || '{customer}';
    return formatTaskWithTemplate(task, templateContent);
  };

  const renderFormattedWhatsAppText = (text: string) => {
    const lines = text.split('\n');
    return lines.map((line, idx) => {
      let formatted = line;
      // Replace *bold* with strong
      formatted = formatted.replace(/\*(.*?)\*/g, '<strong class="font-extrabold text-slate-800">$1</strong>');
      formatted = formatted.replace(/_(.*?)_/g, '<em class="italic">$1</em>');
      formatted = formatted.replace(/~(.*?)_/g, '<del class="line-through opacity-70">$1</del>');
      return (
        <div 
          key={idx} 
          className="min-h-[1.2em] leading-relaxed text-[10px] break-words text-right" 
          dangerouslySetInnerHTML={{ __html: formatted || '&nbsp;' }} 
        />
      );
    });
  };

  const [printingTask, setPrintingTask] = useState<Task | null>(null);
  const [isPrintingReview, setIsPrintingReview] = useState(false);
  const [reviewPrintValues, setReviewPrintValues] = useState<any>(null);


  const handlePrintReview = () => {
    // Collect all values dynamically from the inputs and states
    const costVal = (document.querySelector('input[name="cost"]') as HTMLInputElement)?.value || '0.00';
    const currencyVal = (document.querySelector('[name="currency"]') as HTMLSelectElement)?.value || 'RY';
    const depositVal = depositRef.current?.value || '0.00';
    
    const cost = parseFloat(costVal || '0');
    const deposit = parseFloat(depositVal || '0');
    const remaining = Math.max(0, cost - deposit).toFixed(2);

    const execTime = executionTimeRef.current?.value 
      ? new Date(executionTimeRef.current.value).toLocaleString((uiSettings as any)?.dateTimeLocale || 'ar-YE', (uiSettings as any)?.dateTimeOptions || { hour: '2-digit', minute: '2-digit', day: 'numeric', month: 'short' }) 
      : 'غير محدد';

    setReviewPrintValues({
      customer: customerSearch || '',
      phones: taskCustomerPhones,
      devices: [...taskDevices],
      issue: taskIssueText || 'لا يوجد وصف مضاف.',
      cost: costVal,
      deposit: depositVal,
      remaining: remaining,
      currency: currencyVal,
      executionTime: execTime,
      createdAt: new Date().toISOString()
    });

    setIsPrintingReview(true);
    document.body.classList.add('printing-review-active');

    setTimeout(() => {
      try {
        if ((window as any).AndroidInterface && (window as any).AndroidInterface.print) {
          (window as any).AndroidInterface.print();
        } else if ((window as any).webkit && (window as any).webkit.messageHandlers && (window as any).webkit.messageHandlers.print) {
          (window as any).webkit.messageHandlers.print.postMessage({});
        } else {
          window.print();
        }
      } catch (e) {
        console.error('Print review error', e);
        window.print();
      }
      setTimeout(() => {
        document.body.classList.remove('printing-review-active');
        setIsPrintingReview(false);
        setReviewPrintValues(null);
      }, 15000); // Increased timeout for Android print spooler
    }, 250);
  };

  const handlePrintReviewAsImage = async () => {
    try {
      // static import used
      const element = document.getElementById('receipt-live-preview-box');
      if (!element) {
        alert('حدث خطأ: لم يتم العثور على مساحة السند لتصويرها (تأكد من فتح المعاينة أولاً).');
        return;
      }
      
      const clone = element.cloneNode(true) as HTMLElement;
      Object.assign(clone.style, {
        position: 'absolute',
        top: '-9999px',
        left: '-9999px',
        width: element.offsetWidth + 'px',
        height: 'auto',
        maxHeight: 'none',
        overflow: 'visible',
        transform: 'none',
      });
      document.body.appendChild(clone);

      const expSettings = getExportSettings();
      const dims = resolveExportDimensions(expSettings, false);

      const { default: html2canvasDyn } = await import('html2canvas-pro');
      const canvas = await html2canvasDyn(clone, {
        useCORS: true,
        allowTaint: true,
        backgroundColor: receiptTemplate === 'luxury' ? '#090d16' : (expSettings.backgroundColor || '#ffffff'),
        scale: dims.scale,
      });

      document.body.removeChild(clone);

      const imgMime = expSettings.imageFormat || 'image/png';
      const imgExt = imgMime === 'image/jpeg' ? 'jpg' : (imgMime === 'image/webp' ? 'webp' : 'png');

      canvas.toBlob(async (blob) => {
        if (!blob) {
          alert('تعذر توليد صورة السند.');
          return;
        }
        
        const fileSuf = `${customerSearch || 'عميل'}_${new Date().toISOString().split('T')[0]}`;
        const fileName = `سند_صيانة_${fileSuf}.${imgExt}`;
        
        await downloadBlob(blob, fileName);
        toast.success(`تم حفظ صورة السند في ملفات الهاتف: ${fileName}`);
      }, imgMime, expSettings.imageQuality || 0.95);
    } catch (error) {
      console.error('Error capture receipt image:', error);
      alert('حدث خطأ أثناء محاولة تصوير ومشاركة السند كصورة.');
    }
  };

  const handlePrintSingleTask = (task: Task) => {
    setPrintingTask(task);
    document.body.classList.add('printing-task-active');
  };

  useEffect(() => {
    (window as any).onContactPicked = (name: string, phone: string) => {
      const cleanPhone = phone?.replace(/[^\d+]/g, '').trim();
      const cleanName = name?.trim();
      
      if (cleanPhone) {
        setPhoneInputValue(cleanPhone);
        setTaskCustomerPhones(prev => {
          if (!prev.includes(cleanPhone)) return [...prev, cleanPhone];
          return prev;
        });
      }
      if (cleanName) {
        const custInput = document.querySelector('input[name="customer"]') as HTMLInputElement;
        if (custInput && (!custInput.value || custInput.value.trim() === 'عميل' || custInput.value.trim() === '')) {
            custInput.value = cleanName;
            setCustomerSearch(cleanName);
        }
      }
    };
    return () => {
      delete (window as any).onContactPicked;
    };
  }, []);
  
  useEffect(() => {
    const now = new Date();
    let start = new Date();
    let end = new Date();

        if (dashboardFilter === 'today') {
      start.setHours(0, 0, 0, 0);
      end.setHours(23, 59, 59, 999);
    } else if (dashboardFilter === 'week') {
      const day = now.getDay();
      const diffToSaturday = day === 6 ? 0 : day + 1;
      start.setDate(now.getDate() - diffToSaturday);
      start.setHours(0, 0, 0, 0);
      end = new Date(start);
      end.setDate(start.getDate() + 6);
      end.setHours(23, 59, 59, 999);
    } else if (dashboardFilter === 'month') {
      start = new Date(now.getFullYear(), now.getMonth(), 1);
      start.setHours(0, 0, 0, 0);
      end = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59, 999);
    } else if (dashboardFilter === 'year') {
      start = new Date(now.getFullYear(), 0, 1);
      start.setHours(0, 0, 0, 0);
      end = new Date(now.getFullYear(), 11, 31, 23, 59, 59, 999);
    } else if (dashboardFilter === 'specific_month') {
      const [year, month] = selectedMonth.split('-').map(Number);
      start = new Date(year, month - 1, 1);
      end = new Date(year, month, 0, 23, 59, 59, 999);
    } else if (dashboardFilter === 'custom') {
      return; // Handled by manual input
    }

    if (true) {
      // Create local time ISO strings
      const startStr = new Date(start.getTime() - (start.getTimezoneOffset() * 60000)).toISOString().split('T')[0];
      const endStr = new Date(end.getTime() - (end.getTimezoneOffset() * 60000)).toISOString().split('T')[0];
      setDashboardStartDate(startStr);
      setDashboardEndDate(endStr);
    }
  }, [dashboardFilter, selectedMonth]);

  const accountsStats = useMemo(() => {
    if (!tasks || !transactions) return { totalIncome: 0, totalExpenses: 0, revenue: 0 };

    const start = new Date(dashboardStartDate + "T00:00:00");
    const end = new Date(dashboardEndDate + "T23:59:59");

    const filteredTasks = tasks.filter(t => {
      const d = new Date(t.createdAt);
      if (d < start || d > end) return false;
      
      if (accountsFilterType === 'customer') return t.customer === accountsFilterValue;
      if (accountsFilterType === 'classification') {
        const customer = customers.find(c => c.name === t.customer);
        return customer?.classification === accountsFilterValue;
      }
      if (accountsFilterType === 'sale') return t.taskType === 'sale';
      if (accountsFilterType === 'purchase') return t.taskType === 'purchase';
      if (accountsFilterType === 'expense' || accountsFilterType === 'inventory' || accountsFilterType === 'expense_category') return false;
      return true;
    });

    const filteredTransactions = transactions.filter(t => {
      const d = new Date(t.date);
      if (d < start || d > end) return false;

      if (accountsFilterType === 'customer') return t.customerName === accountsFilterValue;
      if (accountsFilterType === 'classification') {
        const customer = customers.find(c => c.name === t.customerName);
        return customer?.classification === accountsFilterValue;
      }
      if (accountsFilterType === 'sale') {
        if (t.isTask && t.taskId) {
          const associatedTask = tasks.find(tk => tk.id === t.taskId);
          return associatedTask?.taskType === 'sale';
        }
        return t.category === 'مبيعات';
      }
      if (accountsFilterType === 'purchase') {
        if (t.isTask && t.taskId) {
          const associatedTask = tasks.find(tk => tk.id === t.taskId);
          return associatedTask?.taskType === 'purchase';
        }
        return t.category === 'مشتريات' || t.category === 'مخزون';
      }
      if (accountsFilterType === 'expense') return t.type === 'expense';
      if (accountsFilterType === 'inventory') return t.category === 'مشتريات' || t.category === 'مخزون';
      if (accountsFilterType === 'expense_category') return t.type === 'expense' && t.category === accountsFilterValue;
      return true;
    });

    const toSysInt = (amount: number, cur: string) => convertAndRound(amount, cur as Currency, systemCurrency, exchangeRates);
    
    const taskIncomeSys = filteredTasks.reduce((sum, t) => sum + toSysInt(t.deposit || 0, t.currency), 0);
    const taskCostSys = filteredTasks.reduce((sum, t) => sum + toSysInt(t.cost || 0, t.currency), 0);

    const manualIncomeSys = filteredTransactions
      .filter(t => t.type === 'income' && !t.isTask)
      .reduce((sum, t) => sum + toSysInt(t.amount, t.currency), 0);

    const manualExpenseSys = filteredTransactions
      .filter(t => t.type === 'expense')
      .reduce((sum, t) => sum + toSysInt(t.amount, t.currency), 0);

    const totalIncomeSys = taskIncomeSys + manualIncomeSys;
    const totalExpensesSys = taskCostSys + manualExpenseSys;
    const revenueSys = totalIncomeSys - totalExpensesSys;

    return {
      totalIncome: convertCurrency(totalIncomeSys, systemCurrency, 'USD', exchangeRates),
      totalExpenses: convertCurrency(totalExpensesSys, systemCurrency, 'USD', exchangeRates),
      revenue: convertCurrency(revenueSys, systemCurrency, 'USD', exchangeRates)
    };
  }, [tasks, transactions, exchangeRates, systemCurrency, dashboardStartDate, dashboardEndDate, accountsFilterType, accountsFilterValue, customers]);

  // Stats
  const stats = useMemo(() => {
    if (!tasks || !transactions) return { pending: 0, inProgress: 0, inspected: 0, maintenanceDone: 0, delivered: 0, completedInPeriod: 0, revenue: 0, totalIncome: 0, totalExpenses: 0, dynamicStatsBar: {} };

    const start = new Date(dashboardStartDate + "T00:00:00");
    const end = new Date(dashboardEndDate + "T23:59:59");

    const filteredTasks = tasks.filter(t => {
      const d = new Date(t.createdAt);
      return d >= start && d <= end;
    });

    const dynamicStatsBar: Record<string, number> = {};
    const statsBarItems = uiSettings?.statsBarItems || DEFAULT_UI_SETTINGS.statsBarItems;
    
    statsBarItems.forEach((item: any) => {
      dynamicStatsBar[item.id] = filteredTasks.reduce((sum, t) => {
        if (item.statuses.includes(t.status)) {
          if ((t.status === 'completed' || t.status === 'cancelled-delivered') && t.devices && Array.isArray(t.devices)) {
            return sum + t.devices.reduce((dSum: number, d: any) => dSum + (d.quantity || 1), 0);
          }
          return sum + 1;
        }
        return sum;
      }, 0);
    });

    const pending = dynamicStatsBar['pending'] || filteredTasks.filter(t => t.status === 'pending').length;
    const inspected = dynamicStatsBar['inspected'] || filteredTasks.filter(t => ['inspected', 'reported-in-progress', 'reported-cancelled'].includes(t.status)).length;
    const inProgress = dynamicStatsBar['inProgress'] || filteredTasks.filter(t => t.status === 'in-progress').length;
    const maintenanceDone = dynamicStatsBar['maintenanceDone'] || filteredTasks.filter(t => t.status === 'maintenance-done' || t.status === 'ready-to-deliver').length;
    const deliveredCount = dynamicStatsBar['delivered'] || filteredTasks.reduce((sum, t) => {
      if (t.status === 'completed' || t.status === 'cancelled-delivered') {
        if (t.devices && Array.isArray(t.devices)) {
          return sum + t.devices.reduce((dSum: number, d: any) => dSum + (d.quantity || 1), 0);
        }
        return sum + 1;
      }
      return sum;
    }, 0);
    
    const completedTasksInPeriodCount = filteredTasks.reduce((acc, t) => {
      if (t.status === 'completed' || t.status === 'cancelled-delivered') {
        if (t.devices && Array.isArray(t.devices)) {
          return acc + t.devices.reduce((sum: number, dev: any) => sum + (dev.quantity || 1), 0);
        }
        return acc + 1;
      }
      return acc;
    }, 0);

    const taskIncomeSys = filteredTasks.reduce((sum, t) => {
      const toSysInt = (amount: number, cur: string) => convertAndRound(amount, cur as Currency, systemCurrency, exchangeRates);
      if (t.status === 'completed' || t.status === 'cancelled-delivered') return sum + toSysInt(t.cost, t.currency);
      if (['in-progress', 'maintenance-done', 'ready-to-deliver', 'inspected', 'reported-in-progress', 'reported-cancelled'].includes(t.status)) return sum + toSysInt(t.deposit || 0, t.currency);
      return sum;
    }, 0);

    const manualIncomeSys = transactions
      .filter(t => {
        const d = new Date(t.date);
        return t.type === 'income' && !t.isTask && d >= start && d <= end;
      })
      .reduce((sum, t) => sum + convertAndRound(t.amount, t.currency, systemCurrency, exchangeRates), 0);

    const expensesSys = transactions
      .filter(t => {
        const d = new Date(t.date);
        return t.type === 'expense' && d >= start && d <= end;
      })
      .reduce((sum, t) => sum + convertAndRound(t.amount, t.currency, systemCurrency, exchangeRates), 0);
    
    return {
      pending: pending,
      inProgress,
      inspected,
      maintenanceDone,
      delivered: deliveredCount,
      completedInPeriod: completedTasksInPeriodCount,
      revenue: convertCurrency(taskIncomeSys + manualIncomeSys - expensesSys, systemCurrency, 'USD', exchangeRates),
      totalIncome: convertCurrency(taskIncomeSys + manualIncomeSys, systemCurrency, 'USD', exchangeRates),
      totalExpenses: convertCurrency(expensesSys, systemCurrency, 'USD', exchangeRates),
      dynamicStatsBar
    };
  }, [tasks, transactions, exchangeRates, systemCurrency, dashboardStartDate, dashboardEndDate]);  // Report States
  const [reportPeriod, setReportPeriod] = useState<'daily' | 'weekly' | 'monthly' | 'yearly' | 'custom'>('monthly');
