  const getGroupedAndSortedTasks = (filteredTasks: Task[]) => {
    const isSmartRank = taskSort.startsWith('rank_');
    if (!isSmartRank) return null;

    const groupMap: Record<string, { tasks: Task[], revenue: number, count: number }> = {};
    const toSysInt = (amount: number, cur: string) => convertAndRound(amount, cur as Currency, systemCurrency, exchangeRates);

    filteredTasks.forEach(t => {
      let key = '';
      const taskDate = new Date(t.createdAt);
      const rev = toSysInt(t.deposit || 0, t.currency);

      if (taskSort.includes('days')) {
        key = t.createdAt ? t.createdAt.split('T')[0] : 'غير مسمى';
      } else if (taskSort.includes('months')) {
        key = t.createdAt ? taskDate.toLocaleDateString('ar-YE', { year: 'numeric', month: 'long' }) : 'غير محدد';
      } else if (taskSort.includes('years')) {
        key = t.createdAt ? `${taskDate.getFullYear()}` : 'غير محدد';
      } else if (taskSort.includes('device_types')) {
        key = t.deviceType || 'أجهزة متنوعة';
      } else if (taskSort.includes('device_brands')) {
        key = t.brand || 'ماركة متنوعة';
      } else if (taskSort.includes('categories')) {
        key = t.issue || 'صيانة عامة';
      } else if (taskSort.includes('customers')) {
        key = t.customer || 'عميل نقدي';
      }

      if (!groupMap[key]) {
        groupMap[key] = { tasks: [], revenue: 0, count: 0 };
      }
      groupMap[key].tasks.push(t);
      groupMap[key].revenue += rev;
      groupMap[key].count += 1;
    });

    const groupsArray = Object.entries(groupMap).map(([label, val]) => ({
      label,
      tasks: val.tasks,
      revenueUSD: convertCurrency(val.revenue, systemCurrency, 'USD', exchangeRates),
      taskCount: val.count
    }));

    groupsArray.sort((a, b) => {
      const isRevenueSort = taskSort.endsWith('revenue') || taskSort === 'rank_customers';
      if (isRevenueSort) {
        return b.revenueUSD - a.revenueUSD;
      } else {
        return b.taskCount - a.taskCount;
      }
    });

    groupsArray.forEach(grp => {
      grp.tasks.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
    });

    return groupsArray;
  };
  
