  const [loginView, setLoginView] = useState<'keypad' | 'users'>('keypad');
  const [selectedLoginUser, setSelectedLoginUser] = useState<User | null>(null);
  const users = useLiveQuery(() => db.users.toArray()) || [];

  const [isScreenshotMode, setIsScreenshotMode] = useState(false);

  useEffect(() => {
    const handlePopState = () => {
      if (isScreenshotMode) {
        setIsScreenshotMode(false);
      }
    };
    window.addEventListener('popstate', handlePopState);


    return () => {
      window.removeEventListener('popstate', handlePopState);
    };
  }, [isScreenshotMode]);
  const [exportMethodsTarget, setExportMethodsTarget] = useState<'image' | 'pdf'>('image');

  const [isExportModalOpen, setIsExportModalOpen] = useState(false);
  const [exportType, setExportType] = useState<'image' | 'pdf' | 'backup' | null>(null);
  const [exportBlob, setExportBlob] = useState<Blob | null>(null);
  const [exportFileName, setExportFileName] = useState('');
  const [exportStringData, setExportStringData] = useState<string | null>(null); // For backup/text
  const [isExporting, setIsExporting] = useState(false);
  const [receiptPrintMode, setReceiptPrintMode] = useState<'all' | 'financial_only' | 'services_only'>('all');
  const [isBackingUp, setIsBackingUp] = useState(false);

  useEffect(() => {
    // Session validation after users are loaded
    if (users.length > 0 && !currentUser) {

      const isDefaultOnly = users.length === 1 && users[0].username === 'المسؤول' && users[0].pin === '0000';
      const loginFreq = (uiSettings as any)?.loginFrequency || 'logout_only';
      
      // Auto-login logic for disabled login screen (logout_only)
      if ((isDefaultOnly || loginFreq === 'logout_only') && !sessionStorage.getItem('faisali_explicit_logout')) {
        const savedSession = localStorage.getItem('faisali_session');
        let targetUser = users.find(u => u.role === 'admin') || users[0];
        
        if (savedSession) {
           try {
             const { userId } = JSON.parse(savedSession);
             const u = users.find(u => u.id === userId);
             if (u) targetUser = u;
           } catch(e) {}
        }
        
        if (targetUser) {
          setCurrentUser(targetUser);
          setIsLoginModalOpen(false);
          (window as any).currentUser = targetUser;
          localStorage.setItem('faisali_session', JSON.stringify({ userId: targetUser.id, loginTime: Date.now() }));
          sessionStorage.setItem('faisali_session_mem', '1');
          return;
        }
      }


      const savedSession = localStorage.getItem('faisali_session');
      if (savedSession) {
        try {
          const { userId, loginTime } = JSON.parse(savedSession);
          const now = Date.now();
          const loginFreq = (uiSettings as any)?.loginFrequency || 'logout_only';
          const memSession = sessionStorage.getItem('faisali_session_mem');
          
          let requireLogin = false;
          
          if (loginFreq === 'always' || loginFreq === 'close_only') {
            if (!memSession) requireLogin = true;
          } else if (loginFreq === '12h') {
            if (now - loginTime >= 12 * 60 * 60 * 1000) requireLogin = true;
          } else if (loginFreq === 'logout_only') {
            requireLogin = false;
          }

          if (!requireLogin) {
            const user = users.find(u => u.id === userId);
            if (user) {
              setCurrentUser(user);
              setIsLoginModalOpen(false);
              (window as any).currentUser = user;
              if (!memSession) sessionStorage.setItem('faisali_session_mem', '1');
            } else {
              setIsLoginModalOpen(true);
            }
          } else {
            setIsLoginModalOpen(true);
            if (loginFreq === '12h') localStorage.removeItem('faisali_session');
          }
        } catch (e) {
          setIsLoginModalOpen(true);
          localStorage.removeItem('faisali_session');
        }
      } else {
        setIsLoginModalOpen(true);
      }
    }
  }, [users, currentUser]);

  useEffect(() => {
    if (isLoginModalOpen && users.length > 1 && !selectedLoginUser) {
      setLoginView('users');
    } else if (users.length === 1) {
      setLoginView('keypad');
      setSelectedLoginUser(users[0]);
    }
  }, [isLoginModalOpen, users.length]);

  useEffect(() => {
    // Periodic session check
    const interval = setInterval(() => {
      const loginFreq = (uiSettings as any)?.loginFrequency || 'logout_only';
      if (loginFreq !== '12h') return;

      const savedSession = localStorage.getItem('faisali_session');
      if (savedSession) {
        try {
          const { loginTime } = JSON.parse(savedSession);
          if (Date.now() - loginTime >= 12 * 60 * 60 * 1000) {
            setCurrentUser(null);
            setIsLoginModalOpen(true);
            localStorage.removeItem('faisali_session');
          }
        } catch (e) {}
      }
    }, 60000); // Every minute
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    // Visibility change listener for "always" login frequency
    const handleVisibilityChange = () => {
      const loginFreq = (uiSettings as any)?.loginFrequency || 'logout_only';
      if (document.hidden && loginFreq === 'always') {
        const currentU = (window as any).currentUser;
        if (currentU) {
          setCurrentUser(null);
          setIsLoginModalOpen(true);
        }
      }
    };
    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => document.removeEventListener('visibilitychange', handleVisibilityChange);
  }, [uiSettings]);

  useEffect(() => {
    // Create default admin if no users exist
    const setupDefaultAdmin = async () => {
      const count = await db.users.count();
      if (count === 0) {
        await db.users.add({
          username: 'المسؤول',
          pin: '0000',
          role: 'admin',
          permissions: {
            canManageCustomers: true,
            canManageInventory: true,
            canEditOptions: true,
            canChangeFilters: true,
            canAccessAccounts: true,
            canAccessReports: true,
            canViewStats: true,
            canEditTasks: true,
            canDeleteTasks: true,
            canManageUsers: true,
            canChangeSettings: true,
            canViewTaskStatuses: true,
            canExportData: true,
            canImportData: true,
            canUseVoiceAssistant: true,
            canUseTools: true,
            canUseFlashInterface: true,
            canManageQuickNotes: true
          },
          createdAt: new Date().toISOString()
        });
      }
    };
    setupDefaultAdmin();
  }, []);

  const handleLogin = async (pinToUse?: string) => {
    const pin = pinToUse || loginPin;
    const user = selectedLoginUser 
      ? (selectedLoginUser.pin === pin ? selectedLoginUser : null)
      : users.find(u => u.pin === pin);
      
    if (user) {
      setCurrentUser(user);
      setIsLoginModalOpen(false);
      setLoginPin('');
      setLoginError('');
      setSelectedLoginUser(null);
      setLoginView('keypad');
      (window as any).currentUser = user;
      localStorage.setItem('faisali_session', JSON.stringify({
        userId: user.id,
        loginTime: Date.now()
      }));
      sessionStorage.setItem('faisali_session_mem', '1');
    } else {
      setLoginError('كلمة المرور خاطئة. يرجى المحاولة من جديد');
      setTimeout(() => {
        setLoginPin(prev => prev === pin ? '' : prev);
      }, 500);
    }
  };

  

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!isLoginModalOpen || loginView !== 'keypad') return;
      
      // Support keyboard entry of pin (including Eastern Arabic / Hindi digits ٠١٢٣٤٥٦٧٨٩)
      const digitKey = toStandardDigits(e.key);
      if (digitKey >= '0' && digitKey <= '9') {
        setLoginPin(prev => {
          if (prev.length < 4) {
            const newVal = prev + digitKey;
            if (newVal.length === 4) {
              setTimeout(() => handleLogin(newVal), 150);
            }
            return newVal;
          }
          return prev;
        });
        setLoginError('');
      } else if (e.key === 'Backspace') {
        setLoginPin(prev => prev.slice(0, -1));
        setLoginError('');
      } else if (e.key === 'Delete' || e.key === 'Escape') {
        setLoginPin('');
        setLoginError('');
      } else if (e.key === 'Enter') {
        if (loginPin.length >= 4) {
          handleLogin(loginPin);
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isLoginModalOpen, loginView, loginPin]);

  const [taskImage, setTaskImage] = useState<string | null>(null);
  const [selectedFullImage, setSelectedFullImage] = useState<string | null>(null);
  const [taskDevices, setTaskDevices] = useState<{ type: string, brand: string, quantity: number, imageUrls?: string[] }[]>([{ type: '', brand: '', quantity: 1, imageUrls: [] }]);
  const [selectedItems, setSelectedItems] = useState<string[]>([]);
  const [itemCounts, setItemCounts] = useState<Record<string, number>>({});
  const [issueOptions, setIssueOptions] = useState<string[]>([]);
  const [inspectionOptions, setInspectionOptions] = useState<string[]>([]);
  const [accountOptions, setAccountOptions] = useState<string[]>([]);
  const [typeOptions, setTypeOptions] = useState<string[]>([]);
  const [modelOptions, setModelOptions] = useState<string[]>([]);
  const [costOptions, setCostOptions] = useState<string[]>([]);
  const [statusOptions, setStatusOptions] = useState<string[]>([]);
  const [newStatusInput, setNewStatusInput] = useState('');
  const [customerOptions, setCustomerOptions] = useState<string[]>([]);
  const [classificationOptions, setClassificationOptions] = useState<string[]>([]);

  // Keep a ref for double click timing
  const lastBackPressTimeRef = useRef(0);

  // History management for back navigation
  useEffect(() => {
    // Initial push to have something to go back from
    if (!window.history.state || !window.history.state.base) {
      window.history.pushState({ base: true }, '');
    }
    
    const handlePopState = (event: PopStateEvent) => {
      const now = Date.now();
      if (now - (window as any)._lastPopStateTime < 300) return;
      (window as any)._lastPopStateTime = now;

      let handled = false;

      // Close the front-most modal/overlay first
      if (imageSourceChooser) { setImageSourceChooser(null); handled = true; }
      else if (activeStatsDropdown) { setActiveStatsDropdown(null); handled = true; }
      else if (isDashboardTabDropdownOpen) { setIsDashboardTabDropdownOpen(false); handled = true; }
      else if (showCustomerDropdown) { setShowCustomerDropdown(false); handled = true; }
      else if (isSearchFocused || keepSearchOpen) { setIsSearchFocused(false); setKeepSearchOpen(false); handled = true; }
      else if (showNotificationsDropdown) { setShowNotificationsDropdown(false); handled = true; }
      else if (isAssistantMenuOpen) { setIsAssistantMenuOpen(false); handled = true; }
      else if (isAddingNote) { setIsAddingNote(false); handled = true; }
      else if (isFloatingModalOpen) { setIsFloatingModalOpen(false); handled = true; }
      else if (isAddingReminder) { setIsAddingReminder(false); handled = true; }
      else if (selectedFullImage) { setSelectedFullImage(null); handled = true; }
      else if (viewingImagesTask) { setViewingImagesTask(null); handled = true; }
      else if (viewingImagesInventoryItem) { setViewingImagesInventoryItem(null); handled = true; }
      else if (quickTransaction && quickTransaction.show) { setQuickTransaction(null); handled = true; }
      else if (isExitConfirmModalOpen) { setIsExitConfirmModalOpen(false); handled = true; }
      else if (isLogoutConfirmOpen) { setIsLogoutConfirmOpen(false); handled = true; }
      else if (isExportModalOpen) { setIsExportModalOpen(false); handled = true; }
      else if (isExportSettingsModalOpen) { setIsExportSettingsModalOpen(false); handled = true; }
      else if (isFontSettingsModalOpen) { setIsFontSettingsModalOpen(false); handled = true; }
      else if (isCustomerFinancialAccountModalOpen) { setIsCustomerFinancialAccountModalOpen(false); handled = true; }
      else if (isAccountReportModalOpen) { setIsAccountReportModalOpen(false); handled = true; }
      else if (isOmniPreviewModalOpen) { setIsOmniPreviewModalOpen(false); handled = true; }
      else if (isReportTemplateModalOpen) { setIsReportTemplateModalOpen(false); handled = true; }
      else if (isTaskFormatModalOpen) { setIsTaskFormatModalOpen(false); handled = true; }
      else if (isPhoneManagerOpen) { setIsPhoneManagerOpen(false); handled = true; }
      else if (isCallSelectorOpen) { setIsCallSelectorOpen(false); handled = true; }
      else if (isWhatsAppShareModalOpen) { setIsWhatsAppShareModalOpen(false); handled = true; }
      else if (isGlobalTemplatePickerOpen) { setIsGlobalTemplatePickerOpen(false); handled = true; }
      else if (isTemplateSettingsOpen) { setIsTemplateSettingsOpen(false); handled = true; }
      else if (isCopySettingsOpen) { setIsCopySettingsOpen(false); handled = true; }
      else if (isDepositHistoryModalOpen) { setIsDepositHistoryModalOpen(false); handled = true; }
      else if (isWindowTitlesModalOpen) { setIsWindowTitlesModalOpen(false); setIsUiCustomizationModalOpen(true); handled = true; }
      else if (isStatusColorsModalOpen) { setIsStatusColorsModalOpen(false); setIsUiCustomizationModalOpen(true); handled = true; }
      else if (isMainButtonsModalOpen) { setIsMainButtonsModalOpen(false); setIsUiCustomizationModalOpen(true); handled = true; }
      else if (isUiCustomizationModalOpen) { setIsUiCustomizationModalOpen(false); setIsSettingsModalOpen(true); handled = true; }
      else if (isTaskInterfaceSettingsModalOpen) { setIsTaskInterfaceSettingsModalOpen(false); setIsSettingsModalOpen(true); handled = true; }
      else if (isTaskDisplayConfigModalOpen) { setIsTaskDisplayConfigModalOpen(false); setIsSettingsModalOpen(true); handled = true; }
      else if (isAppSettingsModalOpen) { setIsAppSettingsModalOpen(false); setIsSettingsModalOpen(true); handled = true; }
      else if (isAdvancedFeaturesModalOpen) { setIsAdvancedFeaturesModalOpen(false); setIsSettingsModalOpen(true); handled = true; }
      else if (isDefaultsModalOpen) { setIsDefaultsModalOpen(false); setIsSettingsModalOpen(true); handled = true; }
      else if (isRatesModalOpen) { setIsRatesModalOpen(false); setIsSettingsModalOpen(true); handled = true; }
      else if (isBackupModalOpen) { setIsBackupModalOpen(false); setIsSettingsModalOpen(true); handled = true; }
      else if (isUserManagementModalOpen) { setIsUserManagementModalOpen(false); setIsSettingsModalOpen(true); handled = true; }
      else if (isReportSchedulingModalOpen) { setIsReportSchedulingModalOpen(false); setIsSettingsModalOpen(true); handled = true; }
      else if (isSystemResetModalOpen) { setIsSystemResetModalOpen(false); setIsSettingsModalOpen(true); handled = true; }
      else if (isAboutModalOpen) { setIsAboutModalOpen(false); setIsSettingsModalOpen(true); handled = true; }
      else if (isGlobalVoiceSettingsOpen) { setIsGlobalVoiceSettingsOpen(false); setIsSettingsModalOpen(true); handled = true; }
      else if (isSettingsModalOpen) { setIsSettingsModalOpen(false); handled = true; }
      else if (isLoginModalOpen && loginView === 'users') { 
        setLoginView('keypad'); 
        if (!selectedLoginUser && users.length > 0) setSelectedLoginUser(users[0]);
        handled = true;
      }
      else if (isTaskModalOpen) { setIsTaskModalOpen(false); setEditingId(null); handled = true; }
      else if (isCustomerModalOpen) { setIsCustomerModalOpen(false); handled = true; }
      else if (isAccountModalOpen) { setIsAccountModalOpen(false); setAccountEditingId(null); handled = true; }
      else if (isInventoryModalOpen) { setIsInventoryModalOpen(false); handled = true; }
      else if (isTransactionModalOpen) { setIsTransactionModalOpen(false); handled = true; }
      else if (activeAlarmTask) { setActiveAlarmTask(null); handled = true; }
      else if (currentPage !== 'dashboard') { 
        setSearchQuery('');
        setCurrentPage('dashboard'); 
        handled = true; 
      }
      else {
        // Single click: Show exit confirmation modal
        setIsExitConfirmModalOpen(true);
        handled = true;
      }

      if (handled) {
        // Push state again so the next back button press also works
        window.history.pushState({ base: true }, '');
      }
    };

    
    let backButtonListener: any = null;
    const registerCapacitorBackButton = async () => {
      try {
        const { Capacitor } = await import('@capacitor/core');
        if (Capacitor && (await import('@capacitor/core')).Capacitor.isNativePlatform()) {
          const { App: CapApp } = await import('@capacitor/app');
          backButtonListener = await CapApp.addListener('backButton', () => {
            handlePopState(new PopStateEvent('popstate'));
          });
        }
      } catch (e) {
        console.warn('Capacitor backButton init failed:', e);
      }
    };
    registerCapacitorBackButton();

    window.addEventListener('popstate', handlePopState);
    
    return () => {
      window.removeEventListener('popstate', handlePopState);
      if (backButtonListener && backButtonListener.remove) {
        backButtonListener.remove();
      }
    };

  }, [
    isTaskModalOpen, isCustomerModalOpen, isInventoryModalOpen, isTransactionModalOpen,
    isRatesModalOpen, isSettingsModalOpen, isDefaultsModalOpen, isBackupModalOpen, isDashboardFilterModalOpen,
    isClassificationModalOpen, activeAlarmTask, currentPage,
    viewingImagesTask, viewingImagesInventoryItem, selectedFullImage, quickTransaction, isLogoutConfirmOpen, isExportModalOpen,
    isPhoneManagerOpen, isWhatsAppShareModalOpen, isGlobalTemplatePickerOpen,
    isTemplateSettingsOpen, isCopySettingsOpen, isDepositHistoryModalOpen,
    isSystemResetModalOpen, isAboutModalOpen, isAppSettingsModalOpen,
    isWindowTitlesModalOpen, isMainButtonsModalOpen, isStatusColorsModalOpen,
    isUiCustomizationModalOpen, isUserManagementModalOpen, isAdvancedFeaturesModalOpen, isTaskInterfaceSettingsModalOpen, isReportSchedulingModalOpen,
    showNotificationsDropdown, isFloatingModalOpen, isAddingNote, isAddingReminder, isCallSelectorOpen, isLoginModalOpen, loginView, selectedLoginUser
  ]);
  const [incomeCategoryOptions, setIncomeCategoryOptions] = useState<string[]>(['خدمات', 'مبيعات', 'تسديد حساب', 'أخرى']);
  const [expenseCategoryOptions, setExpenseCategoryOptions] = useState<string[]>(['إيجار', 'رواتب', 'كهرباء']);
  const [inventoryCategoryOptions, setInventoryCategoryOptions] = useState<string[]>(INVENTORY_CATEGORIES);
  const [inventoryImages, setInventoryImages] = useState<string[]>([]);
  const [inventoryLinks, setInventoryLinks] = useState<string[]>([]);
  const [selectedCosts, setSelectedCosts] = useState<string[]>([]);
  const [taskModelCosts, setTaskModelCosts] = useState<Record<string, string>>({});

  const syncedTaskModels = useMemo<{ name: string; count: number }[]>(() => {
    const countsMap: Record<string, number> = {};
    taskDevices.forEach(d => {
      if (d.brand && d.brand.trim()) {
        const parsed = parseSelectedOptions(d.brand);
        if (parsed && parsed.length > 0) {
          parsed.forEach(rawName => {
            let name = rawName.trim();
            if (name.includes('] ')) {
              name = name.split('] ')[1].trim();
            }
            if (name) {
              countsMap[name] = (countsMap[name] || 0) + (d.quantity && d.quantity > 1 ? d.quantity : 1);
            }
          });
        } else {
          let name = d.brand.trim();
          if (name.includes('] ')) {
            name = name.split('] ')[1].trim();
          }
          if (name) {
            countsMap[name] = (countsMap[name] || 0) + (d.quantity && d.quantity > 1 ? d.quantity : 1);
          }
        }
      }
    });
    return Object.entries(countsMap).map(([name, count]) => ({ name, count }));
  }, [taskDevices]);

  const syncCostCalculation = (
    currentModelCosts: Record<string, string>,
    currentSelectedCosts: string[]
  ) => {
    let modelsSum = 0;
    syncedTaskModels.forEach(m => {
      const rawVal = currentModelCosts[m.name];
      if (rawVal !== undefined && rawVal.trim() !== '') {
        const unitCost = parseFloat(rawVal) || 0;
        const cnt = m.count && m.count > 1 ? m.count : 1;
        modelsSum += (cnt * unitCost);
      }
    });

    const optionsSum = currentSelectedCosts.reduce((acc, curr) => acc + (parseFloat(curr) || 0), 0);
    const grandTotal = modelsSum + optionsSum;

    const costInput = document.querySelector('input[name="cost"]') as HTMLInputElement;
    if (costInput) {
      costInput.value = grandTotal > 0 ? grandTotal.toString() : (modelsSum > 0 || optionsSum > 0 ? '0' : '');
      costInput.dispatchEvent(new Event('input', { bubbles: true }));
      costInput.dispatchEvent(new Event('change', { bubbles: true }));
    }
  };

  useEffect(() => {
    const hasModelCosts = Object.values(taskModelCosts).some(v => v && parseFloat(v) > 0);
    if (hasModelCosts || selectedCosts.length > 0) {
      syncCostCalculation(taskModelCosts, selectedCosts);
    }
  }, [syncedTaskModels]);
  const [taskIssueText, setTaskIssueText] = useState('');
  const [taskStatus, setTaskStatus] = useState<TaskStatus>('pending');
  const [activeStatsDropdown, setActiveStatsDropdown] = useState<'pending' | 'inProgress' | 'inspected' | 'maintenanceDone' | 'delivered' | 'cancelledTasks' | 'financials' | null>(null);
  const statsBarRef = useRef<HTMLDivElement>(null);
  const [statsBarCoords, setStatsBarCoords] = useState({ top: 0, left: 0, bottom: 0, right: 0, width: 0 });

  const updateStatsBarCoords = () => {
    if (statsBarRef.current) {
      const rect = statsBarRef.current.getBoundingClientRect();
      setStatsBarCoords({
        top: rect.top,
        left: rect.left,
        bottom: rect.bottom,
        right: rect.right,
        width: rect.width,
      });
    }
  };

  useEffect(() => {
    if (activeStatsDropdown) {
      updateStatsBarCoords();
      window.addEventListener('resize', updateStatsBarCoords);
      window.addEventListener('scroll', updateStatsBarCoords, true);
    }
    return () => {
      window.removeEventListener('resize', updateStatsBarCoords);
      window.removeEventListener('scroll', updateStatsBarCoords, true);
    };
  }, [activeStatsDropdown]);
  const issueTextareaRef = useRef<HTMLTextAreaElement>(null);
  const executionTimeRef = useRef<HTMLInputElement>(null);
  const depositRef = useRef<HTMLInputElement>(null);

  // مزامنة حية وفورية: إذا كانت نافذة المهمة مفتوحة لتعديل مهمة معينة، وتم تعديل حالتها أو وقت تنفيذها من الواجهة الفلاشية، يتم تحديث الحالة فوراً
  useEffect(() => {
    if (isTaskModalOpen && editingId) {
      const liveTask = tasks.find(t => t.id === editingId);
      if (liveTask) {
        if (liveTask.status && liveTask.status !== taskStatus) {
          setTaskStatus(liveTask.status);
        }
        if (liveTask.executionTime && executionTimeRef.current) {
          const formattedLocal = formatToDateTimeLocal(liveTask.executionTime);
          if (formattedLocal && executionTimeRef.current.value !== formattedLocal) {
            executionTimeRef.current.value = formattedLocal;
          }
        }
      }
    }
  }, [tasks, isTaskModalOpen, editingId, taskStatus]);

  const setQuickTime = (minutes: number) => {
    if (executionTimeRef.current) {
      const target = new Date(Date.now() + minutes * 60 * 1000);
      executionTimeRef.current.value = formatToDateTimeLocal(target);
    }
  };

  const updateDepositRefTotal = (items: { amount: number, currency: Currency }[]) => {
    if (depositRef.current) {
      const targetCurrencyE = document.querySelector('[name="currency"]') as HTMLSelectElement;
      const targetCurrency = (targetCurrencyE?.value as Currency) || 'RY';
      const total = items.reduce((sum, it) => sum + convertAndRound(it.amount, it.currency, targetCurrency, exchangeRates), 0);
      depositRef.current.value = total.toString();
    }
  };

  useEffect(() => {
    if (!isReverseSyncEnabled) return;
    if (!taskIssueText) return;
    const accountPrefix = 'الحساب: ';
    if (!taskIssueText.includes(accountPrefix)) {
        if (depositHistoryItems.length > 0) {
           setDepositHistoryItems([]);
           updateDepositRefTotal([]);
        }
        return;
    }
    const startIndex = taskIssueText.indexOf(accountPrefix);
    const prefixes = ['الأجهزة: ', 'المشكلة: ', 'الفحص: ', 'موقع الحفظ: ', 'الأصناف: ', 'الحالة: '];
    let endIndex = taskIssueText.length;
    for (const prefix of prefixes) {
        const pIdx = taskIssueText.indexOf(prefix, startIndex + accountPrefix.length);
        if (pIdx !== -1 && pIdx < endIndex) endIndex = pIdx;
    }
    const accountStr = taskIssueText.substring(startIndex + accountPrefix.length, endIndex);
    
    const accountLines = accountStr.split(/       ||\[مبلغ:/).filter(Boolean);
    const newItems = [];
    
    for (const line of accountLines) {
        if (!line.trim() || line.includes('رصيد') || line.includes('عليه') || line.includes('له:')) continue;
        if (!line.includes('مبلغ') && !line.includes('دفعة') && !line.includes('+')) continue;
        
        let processedLine = line;
        processedLine = processedLine.replace(/\b\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4}\b/g, '');
        processedLine = processedLine.replace(/\b\d{1,2}:\d{2}(:\d{2})?\b/g, '');
        
        const numberMatch = processedLine.match(/\b\d+(\.\d+)?\b/);
        if (numberMatch) {
            const amount = parseFloat(numberMatch[0]);
            if (amount === 0) continue;
            
            let currency: Currency | null = null;
            if (processedLine.match(/(USD|usd|دولار|\$)/i)) currency = 'USD';
            else if (processedLine.match(/(SAR|sar|سعودي|ر\.س)/i)) currency = 'SAR';
            else if (processedLine.match(/(RY|ry|ريال|ر\.ي|يمني)/i)) currency = 'RY';
            else {
                const currSelect = document.querySelector('[name="currency"]') as HTMLSelectElement;
                currency = (currSelect?.value as Currency) || 'RY';
            }
            
            newItems.push({ amount, currency });
        }
    }
    
    const currStr = JSON.stringify(depositHistoryItems.map(p => ({ a: p.amount, c: p.currency })));
    const newStr = JSON.stringify(newItems.map(p => ({ a: p.amount, c: p.currency })));
    
    if (currStr !== newStr) {
        const mergedItems = newItems.map((n, i) => {
            const existing = depositHistoryItems[i];
            if (existing && existing.amount === n.amount && existing.currency === n.currency) {
                return existing;
            } else if (existing) {
                return {
                    id: existing.id,
                    amount: n.amount,
                    currency: n.currency,
                    date: existing.date
                };
            }
            return {
               id: Date.now().toString() + Math.random().toString(),
               amount: n.amount,
               currency: n.currency,
               date: new Date().toISOString()
            };
        });
        setDepositHistoryItems(mergedItems);
        updateDepositRefTotal(mergedItems);
    }
  }, [taskIssueText, isReverseSyncEnabled]);

  const setSpecificTime = (type: 'today_4pm' | 'today_9pm' | 'tomorrow_4pm' | 'tomorrow_9pm') => {
    if (executionTimeRef.current) {
      const target = new Date();
      if (type.startsWith('tomorrow')) {
        target.setDate(target.getDate() + 1);
      }
      
      if (type.endsWith('4pm')) target.setHours(16, 0, 0, 0);
      else if (type.endsWith('9pm')) target.setHours(21, 0, 0, 0);
      
      executionTimeRef.current.value = formatToDateTimeLocal(target);
    }
  };

  useEffect(() => {
    if (issueTextareaRef.current) {
      issueTextareaRef.current.style.height = 'auto';
      issueTextareaRef.current.style.height = issueTextareaRef.current.scrollHeight + 'px';
    }
  }, [taskIssueText]);

  const parseSelectedOptionsFromText = (text: string, type: 'issue' | 'inspection' | 'storage' | 'items' | 'account' | 'status' | 'devices') => {
    const prefixes = {
      devices: 'الأجهزة: ',
      issue: 'المشكلة: ',
      inspection: 'الفحص: ',
      storage: 'موقع الحفظ: ',
      items: 'الأصناف: ',
      account: 'الحساب: ',
      status: 'الحالة: '
    };
    
    const prefix = prefixes[type];
    if (!text.includes(prefix)) return [];
    
    const start = text.indexOf(prefix) + prefix.length;
    let end = text.length;
    // Find next prefix to determine end of current section
    Object.values(prefixes).forEach(p => {
      if (p !== prefix) {
        const pIdx = text.indexOf(p, start);
        if (pIdx !== -1 && pIdx < end) {
          end = pIdx;
        }
      }
    });

    const section = text.substring(start, end).trim();
    if (!section) return [];
    
    // Clean section from timestamps and delimiters before parsing options
    const cleanSection = section
      .replace(/\s{2,}\d{2}\/\d{2}\/\d{4}\s{2,}\d{2}:\d{2}/g, '')
      .replace(/\s*\[\+\]\s*/g, ', ')
      .replace(/\s*←\s*/g, ', ')
      .replace(/\s*\+\s*/g, ', ');

    return parseSelectedOptions(cleanSection);
  };

  
  const getTaskThumbnail = (task: Task) => {
    if (!task.imageUrl) return null;
    // The imageUrl field stores joined strings: device1Img1,device1Img2|||device2Img1...
    const firstPart = task.imageUrl.split('|||')[0];
    if (!firstPart) return null;
    const firstImg = firstPart.split(',')[0];
    return firstImg || null;
  };

  const getAllTaskImages = (task: Task) => {
    if (!task.imageUrl) return [];
    return task.imageUrl.split('|||').flatMap(part => part.split(',')).filter(url => url);
  };

  const getTaskFinancials = (task: Task) => {
    const totalCostUSD = getInUSD(task.cost || 0, task.currency || systemCurrency, exchangeRates);
    let totalPaidUSD = 0;
    if (task.depositHistory && task.depositHistory.length > 0) {
      totalPaidUSD = task.depositHistory.reduce((sum, item) => sum + getInUSD(item.amount || 0, item.currency || task.currency || systemCurrency, exchangeRates), 0);
    } else {
      totalPaidUSD = getInUSD(task.deposit || 0, task.currency || systemCurrency, exchangeRates);
    }
    const balanceUSD = totalCostUSD - totalPaidUSD;

    return { 
      totalCost: totalCostUSD, 
      totalPaid: totalPaidUSD, 
      balance: balanceUSD 
    };
  };

  const hasCustomerPhone = (t: Task) => {
    if (t.customerPhones && t.customerPhones.length > 0) return true;
    const cust = customers.find(c => normalizeName(c.name) === normalizeName(t.customer));
    if (cust && ((cust.phones && cust.phones.length > 0) || cust.phone)) return true;
    return false;
  };

  const getCustomerTaskSequenceNumber = (task: Task): number => {
    if (!task.customer) return 1;
    const customerTasks = tasks
      .filter(t => t.customer && t.customer.trim().toLowerCase() === task.customer.trim().toLowerCase())
      .sort((a, b) => new Date(a.createdAt || 0).getTime() - new Date(b.createdAt || 0).getTime());
    const index = customerTasks.findIndex(t => t.id === task.id);
    return index !== -1 ? index + 1 : 1;
  };

  const formatArabicDateTime = (isoString?: string): string => {
    if (!isoString) return '';
    const d = new Date(isoString);
    if (isNaN(d.getTime())) return '';
    
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    
    let hours = d.getHours();
    const minutes = String(d.getMinutes()).padStart(2, '0');
    const ampm = hours >= 12 ? 'م' : 'ص';
    hours = hours % 12;
    hours = hours ? hours : 12;
    const hStr = String(hours).padStart(2, '0');
    
    return `${y}/${m}/${day} ${hStr}:${minutes} ${ampm}`;
  };

  const formatTaskCreationTimestamp = (isoString?: string) => {
    if (!isoString) return { dateStr: '', timeStr: '', fullStr: '' };
    const d = new Date(isoString);
    if (isNaN(d.getTime())) return { dateStr: '', timeStr: '', fullStr: '' };
    
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    
    let hours = d.getHours();
    const minutes = String(d.getMinutes()).padStart(2, '0');
    const ampm = hours >= 12 ? 'م' : 'ص';
    hours = hours % 12;
    hours = hours ? hours : 12;
    const hStr = String(hours).padStart(2, '0');
    
    const dateStr = `${y}/${m}/${day}`;
    const timeStr = `${hStr}:${minutes} ${ampm}`;
    const fullStr = `${dateStr} ${timeStr}`;
    
    return { dateStr, timeStr, fullStr };
  };

    const splitPhoneNumbers = (phoneStr?: string): string[] => {
    if (!phoneStr) return [];
    const parts = phoneStr.split(/[\n,/;|]|\s+-\s+/);
    return parts.map(p => p.trim()).filter(p => p.length >= 3);
  };

  const [phoneCallModalData, setPhoneCallModalData] = useState<{
    isOpen: boolean;
    customerName: string;
    phones: string[];
  }>({
    isOpen: false,
    customerName: '',
    phones: [],
  });

  const handleCallCustomer = useCallback((
    customerName?: string,
    rawPhone?: string,
    rawPhonesArr?: string[],
    task?: Task
  ) => {
    const collectedNumbers: string[] = [];

    if (rawPhonesArr && Array.isArray(rawPhonesArr)) {
      rawPhonesArr.forEach(p => collectedNumbers.push(...splitPhoneNumbers(p)));
    }

    if (rawPhone) {
      collectedNumbers.push(...splitPhoneNumbers(rawPhone));
    }

    if (task) {
      if (task.customerPhones && Array.isArray(task.customerPhones)) {
        task.customerPhones.forEach(p => collectedNumbers.push(...splitPhoneNumbers(p)));
      }
      if ((task as any).phone) {
        collectedNumbers.push(...splitPhoneNumbers((task as any).phone));
      }
    }

    if (customerName && customers) {
      const matchedCustomer = customers.find(
        c => c.name && normalizeName(c.name) === normalizeName(customerName)
      );
      if (matchedCustomer) {
        if (matchedCustomer.phone) {
          collectedNumbers.push(...splitPhoneNumbers(matchedCustomer.phone));
        }
        if (matchedCustomer.phones && Array.isArray(matchedCustomer.phones)) {
          matchedCustomer.phones.forEach(p => collectedNumbers.push(...splitPhoneNumbers(p)));
        }
      }
    }

    const uniquePhones = Array.from(
      new Set(collectedNumbers.map(p => p.trim()).filter(p => p.length > 0))
    );

    if (uniquePhones.length === 0) {
      if (task) {
        handleOpenPhoneManagerForTask(task);
      } else {
        toast.error('لا يوجد رقم هاتف مضاف لهذا العميل. يرجى إضافة رقم الهاتف.');
        if (customerName) {
          setCustomerSearch(customerName);
          setTaskCustomerPhones([]);
          setPhoneInputValue('');
          setIsPhoneManagerOpen(true);
        }
      }
      return;
    }

    if (uniquePhones.length === 1) {
      makeDirectCall(uniquePhones[0]);
    } else {
      setPhoneCallModalData({
        isOpen: true,
        customerName: customerName || 'العميل',
        phones: uniquePhones,
      });
    }
  }, [customers]);

  const makeDirectCall = (phoneNumber: string) => {
    if (!phoneNumber) return;
    const cleanNum = phoneNumber.trim();
    try {
      if ((window as any).AndroidInterface && (window as any).AndroidInterface.phoneCall) {
        (window as any).AndroidInterface.phoneCall(cleanNum);
      } else {
        window.location.href = `tel:${cleanNum}`;
      }
    } catch (err) {
      window.location.href = `tel:${cleanNum}`;
    }
  };
  useEffect(() => {
    const autoArchive = async () => {
      try {
        const now = Date.now();
        const allTasks = await db.tasks.toArray();
        let archivedCount = 0;
        for (const t of allTasks) {
          if (t.status === 'completed') {
            const { balance } = getTaskFinancials(t);
            if (balance <= 0) {
              const updatedAtTime = t.updatedAt ? new Date(t.updatedAt).getTime() : new Date(t.createdAt).getTime();
              // Archive if more than 24 hours have passed since the task was updated (status set to completed)
              if (now - updatedAtTime >= 24 * 60 * 60 * 1000) {
                await db.tasks.update(t.id, { status: 'archived', updatedAt: new Date().toISOString() });
                archivedCount++;
              }
            }
          }
        }
        if (archivedCount > 0) {
          const alertData = { count: archivedCount, date: new Date().toISOString(), isDismissed: false };
          setAutoArchiveAlert(alertData);
          localStorage.setItem('faisali_auto_archive_alert', JSON.stringify(alertData));
          
          // Re-fetch everything after updates to keep state in sync
          const [loadedTasks, loadedTransactions, loadedCustomers, loadedNotes, loadedAuditLogs] = await Promise.all([
             db.tasks.toArray(),
             db.transactions.toArray(),
             db.customers.toArray(),
             db.notes.toArray(),
             db.auditLogs.toArray()
          ]);
          // Use a global or state update if needed, but since we are inside useEffect without dispatch,
          // we can rely on Dexie's live queries or the next component render if we use state.
          // Wait, App uses state for tasks! We should probably update the state directly if possible.
          // But autoArchive is in useEffect without a direct setter in dependencies, it just updates DB.
          // Since we might not have setTasks here, relying on a reload or liveQuery might be needed.
          // Let's reload page or call a function if possible.
        }
      } catch (err) {
        console.error('Auto archive failed', err);
      }
    };
    autoArchive();
    const interval = setInterval(autoArchive, 60 * 60 * 1000);
    return () => clearInterval(interval);
  }, [exchangeRates, systemCurrency, transactions]);


  const appendToIssueText = (current: string, type: 'issue' | 'inspection' | 'account' | 'status' | 'storage' | 'items' | 'deposit' | 'devices', text: string | string[], curr: string = '', replaceStatus: boolean = false) => {
    const prefixes = {
      devices: 'الأجهزة: ',
      issue: 'المشكلة: ',
      inspection: 'الفحص: ',
      storage: 'موقع الحفظ: ',
      items: 'الأصناف: ',
      account: 'الحساب: ',
      status: 'الحالة: '
    };
    
    const now = new Date();
    // Use English numbers (en-GB/en-US)
    const dateStr = now.toLocaleDateString('en-GB', { day: '2-digit', month: '2-digit', year: 'numeric' });
    const timeStr = now.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
    const timestamp = `       ${dateStr}     ${timeStr}`;
    
    const textStr = Array.isArray(text) 
      ? formatSelectedOptions(text, type === 'items' ? 'الأصناف' : (type === 'account' ? 'الحساب' : '')) 
      : text;
    
    // Applying bold numbers to user text as well
    const boldTextStr = boldNumbers(textStr);
    
    const extractPart = (text: string, pType: string) => {
      const p = prefixes[pType as keyof typeof prefixes];
      if (!text.includes(p)) return '';
      const start = text.indexOf(p) + p.length;
      let end = text.length;
      Object.values(prefixes).forEach(val => {
        if (val !== p) {
          const idx = text.indexOf(val, start);
          if (idx !== -1 && idx < end) {
            end = idx;
          }
        }
      });
      return text.substring(start, end).trim();
    };

    // الحفاظ على أي نص أولي مكتوب قبل البادئات
    let leadText = '';
    let minPrefixIdx = -1;
    Object.values(prefixes).forEach(p => {
      const idx = current.indexOf(p);
      if (idx !== -1 && (minPrefixIdx === -1 || idx < minPrefixIdx)) {
        minPrefixIdx = idx;
      }
    });

    if (minPrefixIdx > 0) {
      leadText = current.substring(0, minPrefixIdx).trim();
    } else if (minPrefixIdx === -1 && current.trim()) {
      leadText = current.trim();
    }

    let devices = extractPart(current, 'devices');
    let issue = extractPart(current, 'issue');
    let inspection = extractPart(current, 'inspection');
    let account = extractPart(current, 'account');
    let items = extractPart(current, 'items');
    let status = extractPart(current, 'status');
    let storage = extractPart(current, 'storage');

    // دمج النص الأولي غير المعلم مع وصف المشكلة لضمان عدم فقده مطلقاً
    if (leadText) {
      if (issue) {
        if (!issue.includes(leadText)) issue = `${leadText}\n[+] ${issue}`;
      } else {
        issue = leadText;
      }
    }

    if (type === 'devices') {
      devices = boldTextStr;
    } else if (type === 'issue') {
      if (boldTextStr) {
        if (issue && !replaceStatus) {
          issue += `\n${boldTextStr}`;
        } else {
          issue = boldTextStr;
        }
      }
    } else if (type === 'inspection') {
      const entry = `${boldTextStr}${timestamp}`;
      if (inspection && !replaceStatus) {
        inspection += `\n${entry}`;
      } else {
        inspection = entry;
      }
    } else if (type === 'account') {
      const entry = `${boldTextStr}${timestamp}`;
      if (account && !replaceStatus) {
        account += `\n${entry}`;
      } else {
        account = entry;
      }
    } else if (type === 'items') {
      items = boldTextStr;
    } else if (type === 'status') {
      if (boldTextStr && boldTextStr !== 'غير محدد') {
        const entry = `${boldTextStr}${timestamp}`;
        if (status && !replaceStatus) status += `\n${entry}`;
        else status = entry;
      }
    } else if (type === 'storage') {
      storage = boldTextStr;
    } else if (type === 'deposit') {
      const entry = `مبلغ: ${boldTextStr} ${curr}${timestamp}`;
      if (account && !replaceStatus) account += `\n${entry}`;
      else account = entry;
    }

    // Reconstruct with dedicated full lines for each option/section
    const parts: string[] = [];
    
    if (devices) {
      parts.push(`${prefixes.devices}${devices}`);
    }
    if (issue) {
      parts.push(`${prefixes.issue}${issue}`);
    }
    if (inspection) {
      parts.push(`${prefixes.inspection}${inspection}`);
    }
    if (account && isHassabIncluded) {
      parts.push(`${prefixes.account}${account}`);
    }
    if (items) {
      parts.push(`${prefixes.items}${items}`);
    }
    if (status) {
      parts.push(`${prefixes.status}${status}`);
    }
    if (storage) {
      parts.push(`${prefixes.storage}${storage}`);
    }

    return parts.join('\n');
  };

  useEffect(() => {
    const interval = setInterval(() => {
      const now = new Date();
      
      // 1. Check task maintenance alarms
      tasks.forEach(task => {
        const status = task.status as string;
        if (task.executionTime && !task.isExecuted && task.isAlarmActive && 
            status !== 'تم التنفيذ' && 
            status !== 'ملغية' && 
            status !== 'إلغاء المهمة' &&
            status !== 'completed' &&
            status !== 'maintenance-done' &&
            status !== 'reported-cancelled' &&
            status !== 'cancelled-delivered') {
          const execTime = parseExecutionTimeToDate(task.executionTime);
          if (execTime) {
            const diffMs = now.getTime() - execTime.getTime();
            // ظهور التنبيه فقط في الوقت المحدد للتنفيذ بالضبط (خلال دقيقتين من وقت التنفيذ)
            if (diffMs >= 0 && diffMs <= 120000) {
              setActiveAlarmTask(task);
              // Deactivate alarm for this task so it doesn't pop up again
              db.tasks.update(task.id!, { isAlarmActive: false });
              
              // Play notification sound
              try {
                if ((window as any).__activeAlarmAudio) {
                  (window as any).__activeAlarmAudio.pause();
                  (window as any).__activeAlarmAudio = null;
                }
                const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3');
                (window as any).__activeAlarmAudio = audio;
                audio.play().catch(e => console.warn('Audio play failed:', e));
              } catch (e) {
                console.warn('Audio creation failed:', e);
              }

              // Show native notification
              showNotificationNative('تنبيه صيانة', `موعد صيانة جهاز: ${task.customer} - ${task.deviceType}`);
            } else if (diffMs > 120000) {
              // إذا تجاوز وقت وتاريخ التنفيذ المحدد، منع ظهور الإشعارات والتنبيهات
              db.tasks.update(task.id!, { isAlarmActive: false });
            }
          }
        }
      });

      // 2. Check Custom Alerts
      try {
        const storedStr = localStorage.getItem('faisali_custom_alerts') || '[]';
        const parsedAlerts: CustomAlert[] = JSON.parse(storedStr);
        let updated = false;

        parsedAlerts.forEach(alert => {
          if (!alert.isTriggered && !alert.isDismissed) {
            const alertTime = new Date(alert.dateTime);
            if (now >= alertTime) {
              alert.isTriggered = true;
              updated = true;
              setActiveCustomAlert(alert);

              // Play sound
              try {
                const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3');
                audio.play().catch(e => console.warn('Audio play failed:', e));
              } catch (e) {
                console.warn('Audio creation failed:', e);
              }

              showNotificationNative('تنبيه مخصص جديد', alert.text);
            }
          }
        });

        if (updated) {
          setCustomAlerts(parsedAlerts);
          localStorage.setItem('faisali_custom_alerts', JSON.stringify(parsedAlerts));
          setAlertsRefreshTrigger(prev => prev + 1);
        }
      } catch (err) {
        console.warn('Custom alarms check failed:', err);
      }

      // 3. Check Backup Reminder
      try {
        const lastBackupDate = localStorage.getItem('faisali_last_backup_reminder_date');
        const todayStr = now.toISOString().split('T')[0];
        
        if (lastBackupDate !== todayStr) {
          const dayOfWeek = now.getDay();
          // 0=Sun, 1=Mon, 2=Tue, 3=Wed, 4=Thu, 5=Fri, 6=Sat
          const targetHour = [23, 14, 23, 14, 23, 14, 14][dayOfWeek];
          
          if (now.getHours() >= targetHour) {
            localStorage.setItem('faisali_last_backup_reminder_date', todayStr);
            if (safeConfirm('حان موعد النسخ الاحتياطي الدوري، هل تريد الانتقال لصفحة النسخ الاحتياطي الآن؟')) {
              setIsBackupModalOpen(true);
            }
          }
        }
      } catch (err) {
        console.warn('Backup reminder check failed:', err);
      }

    }, 10000); // Check every 10 seconds
    return () => clearInterval(interval);
  }, [tasks, customAlerts]);

