  const handleSyncIssueDescription = () => {
    if (!taskIssueText) return;
    
    // 1. Update devices part based on taskDevices state
    const devicesList = taskDevices
      .map(d => `${d.quantity > 1 ? `(${d.quantity}) ` : ''}${d.type} ${d.brand}`.trim())
      .filter(s => s);
    
    const devicesText = devicesList.join(' + ');
    
    // 2. Refresh items if they exist in state
    const itemsText = selectedItems.join(' + ');

    setTaskIssueText(prev => {
      let updated = appendToIssueText(prev, 'devices', devicesText);
      if (itemsText) {
        updated = appendToIssueText(updated, 'items', itemsText);
      }
      return updated;
    });
    
    alert('تمت مزامنة التفاصيل بنجاح');
  };

  const handlePrint = () => {
    const reportArea = document.getElementById('report-result-area');
    if (!reportArea) {
      alert('يرجى توليد التقرير أولاً');
      return;
    }
    
    const clone = reportArea.cloneNode(true) as HTMLElement;
    clone.id = 'report-print-clone';
    clone.classList.add('hidden', 'print:block');
    document.body.appendChild(clone);
    document.body.classList.add('printing-active');
    
    try {
      if ((window as any).AndroidInterface && (window as any).AndroidInterface.print) {
        (window as any).AndroidInterface.print();
      } else if ((window as any).webkit && (window as any).webkit.messageHandlers && (window as any).webkit.messageHandlers.print) {
        (window as any).webkit.messageHandlers.print.postMessage({});
      } else {
        window.print();
      }
    } catch (e) {
      console.error('Window print error', e);
      window.print();
    }
    
    setTimeout(() => {
      document.body.classList.remove('printing-active');
      if (document.body.contains(clone)) {
        document.body.removeChild(clone);
      }
    }, 15000); // Increased timeout for Android print spooler
  };



