  const formatTaskWithTemplate = (task: Task, templateContent: string) => {
    const { totalCost, totalPaid, balance } = getTaskFinancials(task);
    const customerObj = customers.find(c => c.name === task.customer);
    
    // Dates handling
    const formatDateStr = (dateStr: string | undefined, show: boolean) => {
      if (!dateStr || !show) return '';
      return new Date(dateStr).toLocaleString('ar-SA');
    };

    const taskDateVisible = reportElements.includes('وقت وتاريخ المهام');
    const inspectionDateVisible = reportElements.includes('وقت وتاريخ الفحص');
    const issueDateVisible = reportElements.includes('وقت وتاريخ المشكلة');
    const statusDateVisible = reportElements.includes('وقت وتاريخ الحالة');
    const accountDateVisible = reportElements.includes('وقت وتاريخ الحساب');
    const paymentsDateVisible = reportElements.includes('وقت وتاريخ المدفوعات');

    const isSale = task.taskType === 'sale';
    const isPurchase = task.taskType === 'purchase';
    const isSaleOrPurchase = isSale || isPurchase;

    // Financial summary
    let financialSummary = `💰 كلي: ${formatAmount(totalCost, systemCurrency, exchangeRates)}💸 مدفوع: ${formatAmount(totalPaid, systemCurrency, exchangeRates)}🧾 رصيد: ${balance > 0 ? 'عليه: ' : (balance < 0 ? 'له: ' : 'خالص: ')}${formatAmount(Math.abs(balance), systemCurrency, exchangeRates)}`;
    if (accountDateVisible || paymentsDateVisible) {
      financialSummary += `📅 تحديث: ${new Date().toLocaleString('ar-SA')}`;
    }

    // Extracting content with optional dates from issue text
    const cleanIssueTextInternal = (type: string, showDate: boolean) => {
      const regex = new RegExp(`\\[${type}: ([^\\]]+)\\]`, 'g');
      const matches = task.issue.match(regex);
      if (!matches) return 'غير محدد';
      return matches.map(m => {
        let content = m.replace(`[${type}: `, '').replace(']', '');
        if (showDate && task.createdAt) {
          content += ` (${new Date(task.createdAt).toLocaleString('ar-SA')})`;
        }
        return content;
      }).join(', ');
    };

    const replacements: Record<string, string> = {
      '{customer}': task.customer,
      '{phone}': customerObj?.phone || '',
      '{device}': task.deviceType,
      '{brand}': task.brand,
      '{model}': (task as any).deviceModel || task.brand,
      '{issue}': isSaleOrPurchase ? '' : task.issue.split('━━━━━━━━━━')[0].trim() + (issueDateVisible ? ` (${new Date(task.createdAt).toLocaleString('ar-SA')})` : ''),
      '{inspection}': isSaleOrPurchase ? '' : cleanIssueTextInternal('فحص', inspectionDateVisible),
      '{status}': getStatusLabel(task.status) + (statusDateVisible ? ` (${new Date().toLocaleString('ar-SA')})` : ''),
      '{cost}': `${formatAmount(totalCost, systemCurrency, exchangeRates)} ${systemCurrency}`,
      '{deposit}': `${formatAmount(totalPaid, systemCurrency, exchangeRates)} ${systemCurrency}`,
      '{balance}': `${formatAmount(balance, systemCurrency, exchangeRates)} ${systemCurrency}`,
      '{createdAt}': formatDateStr(task.createdAt, taskDateVisible),
      '{executionTime}': isSaleOrPurchase ? '' : formatDateStr(task.executionTime, taskDateVisible),
      '{storage}': task.storageLocation || '',
      '{financial_summary}': financialSummary,
    };

    let text = templateContent;
    Object.entries(replacements).forEach(([key, val]) => {
      text = text.replace(new RegExp(key, 'g'), val);
    });

    if (isSaleOrPurchase) {
      const word = isSale ? 'مبيعات' : 'مشتريات';
      text = text.replace(/صيانة/g, word);
    }
    
    return text.split('\n').filter(line => line.trim() !== '').join('\n');
  };

