  const triggerImageSelect = async (mode: 'camera' | 'gallery' | 'files') => {
    if ((window as any).AndroidInterface && (window as any).AndroidInterface.pickImage) {
      try {
        (window as any).onImagePicked = (base64Data: string) => {
          if (base64Data && imageSourceChooser?.onSelected) {
            // Ensure base64 string has standard header if missing
            const dataUrl = base64Data.startsWith('data:') ? base64Data : `data:image/jpeg;base64,${base64Data}`;
            imageSourceChooser.onSelected([dataUrl]);
            setImageSourceChooser(null);
          }
        };
        (window as any).AndroidInterface.pickImage(mode);
        return;
      } catch (err) {
        console.error("Native pickImage failed", err);
      }
    }

    // Fallback to standard web inputs
    if (mode === 'camera') {
      cameraInputRef.current?.click();
    } else if (mode === 'gallery') {
      galleryInputRef.current?.click();
    } else {
      filesInputRef.current?.click();
    }
  };

  const handleImageSourceSelected = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);
    if (files.length === 0) return;
    
    const loadedUrls: string[] = [];
    let processed = 0;
    
    files.forEach(file => {
      const reader = new FileReader();
      reader.onloadend = () => {
        loadedUrls.push(reader.result as string);
        processed++;
        if (processed === files.length) {
          if (imageSourceChooser?.onSelected) {
            imageSourceChooser.onSelected(loadedUrls);
          }
          setImageSourceChooser(null);
        }
      };
      reader.readAsDataURL(file);
    });
    
    // Clear value to allow same option re-selection
    e.target.value = '';
  };

