    setTaskCustomerPhones([]);
    setPhoneInputValue('');
    setSelectedItems([]);
    setItemCounts({});
    setSelectedCosts([]);
    setTaskModelCosts({});
    setDepositHistoryItems([]);
    setTaskModalStep(1);
    setSelectedDeviceType('');
    setSelectedTaskType('maintenance');
