    const d = new Date(task.createdAt || task.id || Date.now());
    const isValidDate = !isNaN(d.getTime());
    const now = new Date();
    const isToday = isValidDate && d.getDate() === now.getDate() && d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear();
    const yesterday = new Date(now); yesterday.setDate(now.getDate() - 1);
    const isYesterday = isValidDate && d.getDate() === yesterday.getDate() && d.getMonth() === yesterday.getMonth() && d.getFullYear() === yesterday.getFullYear();
    const creationTimeOnlyStr = isValidDate ? d.toLocaleTimeString('ar-SA', { hour: '2-digit', minute: '2-digit' }) : '';
    const creationDateOnlyStr = isValidDate ? d.toLocaleDateString('ar-SA', { year: '2-digit', month: 'numeric', day: 'numeric' }) : '';
    const timeStr = isValidDate ? (isToday ? creationTimeOnlyStr : (isYesterday ? `أمس ${creationTimeOnlyStr}` : `${creationDateOnlyStr} ${creationTimeOnlyStr}`)) : '';
    const fullCreationTimestamp = isValidDate ? `${d.toLocaleDateString('ar-SA', { year: 'numeric', month: 'numeric', day: 'numeric' })} ${d.toLocaleTimeString('ar-SA', { hour: '2-digit', minute: '2-digit' })}` : timeStr;

