                          const matchesCustomer = taskNorm === targetNorm || (targetNorm && taskNorm.includes(targetNorm)) || (taskNorm && targetNorm.includes(taskNorm));
                          if (!matchesCustomer) return false;
                          if (searchQuery.trim()) return isTaskMatchingSearchQuery(t, searchQuery);
