                    <div className="flex gap-1 items-center">
                      <ColorPickerField value={uiSettings.sidebarBgColor || '#f8fafc'} onChange={(val) => updateUiSettings({ ...uiSettings, sidebarBgColor: val })} hideHexInput={true} />
                    </div>
